TIPO = 'Felicitación de usuarios'


def crear_tipo_ajuste(apps, schema_editor):
    """Tipo de ajuste de desempeño que usan las felicitaciones (catálogo TIPO_AJUSTE). Se crea con id 12 o el
    siguiente libre, para no chocar con los ids 1 a 11 de datos_iniciales.sql."""
    Catalogo = apps.get_model('UsuarioApp', 'Catalogo')
    if Catalogo.objects.filter(tipo='TIPO_AJUSTE', nombre=TIPO).exists():
        return
    ultimo = Catalogo.objects.order_by('-id').values_list('id', flat=True).first() or 0
    Catalogo.objects.create(id=max(ultimo, 11) + 1, tipo='TIPO_AJUSTE', nombre=TIPO, estado='ACTIVO')


def quitar_tipo_ajuste(apps, schema_editor):
    Catalogo = apps.get_model('UsuarioApp', 'Catalogo')
    Catalogo.objects.filter(tipo='TIPO_AJUSTE', nombre=TIPO, ajustes__isnull=True).delete()


